import json

ALLOWED = {'HIGH', 'CRITICAL'}
FIELDS = ['Package', 'Version', 'CVE_ID', 'Severity', 'CVSS_Score',
          'Fixed_Version', 'Title', 'Url']
PROVIDER_PRIORITY = ['nvd', 'ghsa', 'redhat']


def get_cvss(vuln):
    cvss = vuln.get('CVSS') or {}
    providers = list(cvss.keys())
    ordered = [p for p in PROVIDER_PRIORITY if p in providers] + \
              [p for p in providers if p not in PROVIDER_PRIORITY]
    for version_key in ('V3Score', 'V2Score'):
        for p in ordered:
            entry = cvss.get(p) or {}
            score = entry.get(version_key)
            if isinstance(score, (int, float)):
                return score
    return 'N/A'


def has_any_cvss(vuln):
    cvss = vuln.get('CVSS') or {}
    for entry in cvss.values():
        if not isinstance(entry, dict):
            continue
        if entry.get('V3Score') is not None or entry.get('V2Score') is not None:
            return True
    return False


with open('/root/trivy_report.json') as f:
    data = json.load(f)

rows = []
raw_vulns = []
for result in data.get('Results', []):
    for v in result.get('Vulnerabilities') or []:
        sev = (v.get('Severity') or '').upper()
        if sev not in ALLOWED:
            continue
        raw_vulns.append(v)
        rows.append({
            'Package': v.get('PkgName', ''),
            'Version': v.get('InstalledVersion', ''),
            'CVE_ID': v.get('VulnerabilityID', ''),
            'Severity': sev,
            'CVSS_Score': get_cvss(v),
            'Fixed_Version': v.get('FixedVersion') or 'N/A',
            'Title': v.get('Title') or v.get('Description') or '',
            'Url': v.get('PrimaryURL') or '',
        })

with open('/root/security_audit.csv', 'w', newline='', encoding='utf-8') as f:
    w = csv.DictWriter(f, fieldnames=FIELDS)
    w.writeheader()
    w.writerows(rows)

# Verification
with open('/root/security_audit.csv', newline='', encoding='utf-8') as f:
    r = csv.DictReader(f)
    assert r.fieldnames == FIELDS, r.fieldnames
    read_rows = list(r)

assert len(read_rows) == len(rows), (len(read_rows), len(rows))
for row, src in zip(read_rows, raw_vulns):
    assert row['Severity'] in ALLOWED
    if has_any_cvss(src):
        float(row['CVSS_Score'])  # must be numeric
    if src.get('FixedVersion'):
        assert row['Fixed_Version'] == src['FixedVersion']

print(f"rows: {len(read_rows)}")
print("OK")
